class LazySeg:
    def __init__(self, n={{n}}):
        self.n = n
        self.t = [0]*(4*n)
        self.lz = [0]*(4*n)
    def push(self, p, l, r):
        if self.lz[p]:
            m = (l+r)//2
            self.t[2*p] += self.lz[p]*(m-l+1); self.lz[2*p] += self.lz[p]
            self.t[2*p+1] += self.lz[p]*(r-m); self.lz[2*p+1] += self.lz[p]
            self.lz[p] = 0
    def update(self, ql, qr, v, p=1, l=0, r=None):
        if r is None: r = self.n-1
        if ql <= l and r <= qr:
            self.t[p] += v*(r-l+1); self.lz[p] += v; return
        self.push(p, l, r); m = (l+r)//2
        if ql <= m: self.update(ql,qr,v,2*p,l,m)
        if qr > m: self.update(ql,qr,v,2*p+1,m+1,r)
        self.t[p] = self.t[2*p] + self.t[2*p+1]
    def query(self, ql, qr, p=1, l=0, r=None):
        if r is None: r = self.n-1
        if ql <= l and r <= qr: return self.t[p]
        self.push(p, l, r); m = (l+r)//2; s = 0
        if ql <= m: s += self.query(ql,qr,2*p,l,m)
        if qr > m: s += self.query(ql,qr,2*p+1,m+1,r)
        return s
